// One-time setup for the 9-country x 3-persona question-asker account pool
// (question-accounts.json) -- kept separate from accounts.json's single
// general-posting account per country (see CLAUDE.md "국가별 커뮤니티 봇"
// section): accounts.json posts whatever text a human hands it verbatim,
// while this pool only ever carries the "질문자 페르소나" generated by
// generate-question.mjs. Like the country and reply accounts, each row gets
// profiles.is_supporter = true, so it still carries the "서포터" label.
// Creates an auth user + profiles row for each entry still missing a
// profileId in question-accounts.json, then writes the new id back into that
// file. Safe to re-run -- entries that already have a profileId are skipped.
//
// Usage:
//   node --env-file=.env.local bots/setup-question-accounts.mjs [--dry-run]

import { readFileSync, writeFileSync } from "node:fs";
import { randomUUID } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createClient } from "@supabase/supabase-js";

const ACCOUNTS_PATH = fileURLToPath(new URL("./question-accounts.json", import.meta.url));

export function loadQuestionAccounts() {
  return JSON.parse(readFileSync(ACCOUNTS_PATH, "utf8"));
}

function saveQuestionAccounts(accounts) {
  writeFileSync(ACCOUNTS_PATH, JSON.stringify(accounts, null, 2) + "\n");
}

async function main() {
  const dryRun = process.argv.includes("--dry-run");
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) {
    console.error("missing env: NEXT_PUBLIC_SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY");
    process.exit(1);
  }

  const accounts = loadQuestionAccounts();
  const supabase = createClient(url, key, { auth: { persistSession: false } });

  for (const [id, account] of Object.entries(accounts)) {
    if (account.profileId) {
      console.log(`skip ${id}: already set up (${account.profileId})`);
      continue;
    }
    if (dryRun) {
      console.log(`[dry-run] would create ${id}: ${account.nickname} (${account.country})`);
      continue;
    }

    const { data: created, error: userError } = await supabase.auth.admin.createUser({
      email: `bot.question.${id}@gupgup.internal`,
      password: randomUUID() + randomUUID(),
      email_confirm: true,
      user_metadata: { role: "question_bot", questionId: id },
    });
    if (userError) {
      console.error(`${id}: auth user creation failed: ${userError.message}`);
      continue;
    }

    const { error: profileError } = await supabase.from("profiles").insert({
      id: created.user.id,
      nickname: account.nickname,
      country: account.country,
      is_supporter: true,
    });
    if (profileError) {
      console.error(`${id}: profile insert failed: ${profileError.message}`);
      await supabase.auth.admin.deleteUser(created.user.id).catch(() => {});
      continue;
    }

    account.profileId = created.user.id;
    console.log(`${id}: created ${created.user.id} (${account.nickname})`);
  }

  if (!dryRun) saveQuestionAccounts(accounts);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  });
}
